-- RN Master native-format/case-study pilot import. Preserves matrix, cloze, highlight, bow-tie, SATA and MC formats.
begin;
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set02-Case','RN Master Set 2 unfolding case study','A 68-year-old client with chronic obstructive pulmonary disease (60 pack-year smoking history) is admitted with 3 days of increasing dyspnea and a cough producing thick yellow-green sputum. Nurses'' notes, 1400: Client is sitting in a tripod position using accessory neck muscles and pursed-lip breathing. Restless but oriented. Barrel chest and clubbing of the fingers noted. Diminished breath sounds with expiratory wheezes bilaterally and coarse crackles in the right lower lobe. Vital signs: T 101.3°F (38.5°C), HR 108/min, RR 30/min, BP 146/88 mm Hg, SpO2 84% on room air. Arterial blood gas on room air: pH 7.31, PaCO2 62 mm Hg, HCO3 31 mEq/L, PaO2 52 mm Hg. Previous baseline (clinic records): pH 7.37, PaCO2 50 mm Hg, HCO3 30 mEq/L. Other results: WBC 15,800/mm3. Chest x-ray shows a right lower lobe infiltrate.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set03-Case','RN Master Set 3 unfolding case study','A 22-year-old client is admitted to the emergency department after a motorcycle crash. The client was not wearing a helmet. EMS reports the client was unconscious for about 1 minute at the scene, then woke up and was talking. Nurses'' notes, 1400: Alert and oriented x4. GCS 15. Pupils 3 mm, equal, and briskly reactive. Reports headache rated 5/10. Abrasions on the right forearm. Swelling and deformity of the left wrist. BP 128/78 mm Hg, HR 88/min, RR 16/min, SpO2 98% on room air. Head CT has been ordered and is pending. Nurses'' notes, 1600: Increasingly drowsy. Vomited twice in 20 minutes. Opens eyes only to painful stimuli, speaks in confused sentences, and localizes to pain. Right pupil 6 mm and sluggish; left pupil 3 mm and brisk. BP 168/70 mm Hg, HR 54/min, RR 10/min and irregular, SpO2 94% on room air.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set04-Case','RN Master Set 4 unfolding case study','A 19-year-old college student with type 1 diabetes is brought to the emergency department by a roommate. The client has had vomiting and body aches for 2 days and stopped taking insulin "because I wasn''t eating anything." Nurses'' notes, 2200: Lethargic but arousable and oriented. Deep, rapid respirations. Fruity odor on the breath. Dry mucous membranes and poor skin turgor. Reports frequent urination and extreme thirst for 2 days. Abdominal pain rated 6/10. Vital signs: T 99.8°F (37.7°C), HR 124/min, RR 32/min and deep, BP 94/56 mm Hg, SpO2 99% on room air. Laboratory results: glucose 486 mg/dL, arterial pH 7.18, PaCO2 24 mm Hg, HCO3 10 mEq/L, potassium 5.6 mEq/L (3.5–5.0), sodium 131 mEq/L (135–145), anion gap 24 (8–12), serum beta-hydroxybutyrate elevated, BUN 32 mg/dL (7–20), creatinine 1.4 mg/dL (0.6–1.2).','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set05-Case','RN Master Set 5 unfolding case study','A 58-year-old client with end-stage kidney disease receives hemodialysis every Monday, Wednesday, and Friday. The client missed Friday''s session because of a family emergency and arrives at the emergency department on Monday morning. Nurses'' notes, 0730: Reports generalized muscle weakness, tingling in the hands and around the mouth, and shortness of breath when lying down. Crackles in both lung bases. +2 pitting edema in the lower legs. Weight is 4.2 kg above the client''s documented dry weight. Anuric. Left forearm AV fistula with palpable thrill and audible bruit. Vital signs: T 98.2°F (36.8°C), HR 54/min and irregular, RR 24/min, BP 172/98 mm Hg, SpO2 91% on room air. 12-lead ECG: tall, peaked T waves, widened QRS complex, and flattened P waves. Laboratory results: potassium 7.2 mEq/L (3.5–5.0), sodium 133 mEq/L, BUN 110 mg/dL, creatinine 11.2 mg/dL, HCO3 16 mEq/L (22–26), phosphorus 7.8 mg/dL (2.5–4.5), calcium 7.9 mg/dL (8.6–10.2), hemoglobin 9.1 g/dL.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set06-Case','RN Master Set 6 unfolding case study','A 62-year-old client with osteoarthritis who takes ibuprofen 800 mg three times daily is brought to the emergency department by a spouse. The client had two black, tarry stools yesterday and vomited dark material that looked like coffee grounds this morning. Nurses'' notes, 1000: Anxious and pale. Skin cool and clammy. Reports epigastric pain rated 5/10 and lightheadedness when standing. Capillary refill 4 seconds. Abdomen soft and nondistended. Vital signs: T 97.8°F (36.6°C), HR 122/min, RR 24/min, BP 88/52 mm Hg (baseline 140/80), SpO2 95% on room air. Laboratory results: hemoglobin 7.2 g/dL (12–16), hematocrit 22% (36–48), BUN 42 mg/dL (7–20), creatinine 1.0 mg/dL, platelets 240,000/mm3, INR 1.1.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set07-Case','RN Master Set 7 unfolding case study','A 24-year-old client sustained a closed fracture of the left femoral shaft in a motorcycle crash and is in skeletal traction awaiting surgical fixation. Nurses'' notes, day 2 (36 hours after injury), 0600: Client is newly restless and confused, asking "Where am I?" Reports difficulty breathing. Pinpoint reddish-purple spots noted across the upper chest, in both axillae, and on the conjunctivae. Left thigh is swollen, and pain at the fracture site is rated 5/10. Pin sites are clean with a small amount of clear, crusted drainage. Traction weights hang freely. Left pedal pulse is palpable, and toes are warm with brisk capillary refill. Vital signs: T 101.2°F (38.4°C), HR 124/min, RR 30/min, BP 118/70 mm Hg, SpO2 86% on room air. Laboratory results: platelets 98,000/mm3 (on admission: 240,000/mm3), hemoglobin 10.8 g/dL.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set08-Case','RN Master Set 8 unfolding case study','A 54-year-old client with acute myeloid leukemia is on day 10 after induction chemotherapy. The client has a right upper arm peripherally inserted central catheter (PICC). Nurses'' notes, 2000: Client reports shaking chills and says, "I just don''t feel right." Skin warm and flushed. Redness and tenderness about 2 cm around the PICC insertion site, without drainage. Oral mucosa has several small ulcers. Scattered petechiae on both lower legs. Gums bled slightly during mouth care. Pale and reports fatigue. Vital signs: T 101.5°F (38.6°C), HR 118/min, RR 24/min, BP 96/58 mm Hg (baseline 124/76), SpO2 95% on room air. Laboratory results: WBC 0.6 × 10³/mm³, absolute neutrophil count (ANC) 200/mm³, hemoglobin 8.1 g/dL, platelets 22,000/mm³, lactate 2.8 mmol/L (0.5–2.0), creatinine 1.3 mg/dL (baseline 0.9).','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set09-Case','RN Master Set 9 unfolding case study','A 34-year-old client is in the emergency department being treated for acute pyelonephritis. The client reports no known drug allergies. The first dose of IV ceftriaxone was started 10 minutes ago. Nurses'' notes, 1510: Client suddenly reports itching all over, a tight throat, and feeling faint. The nurse notes widespread raised, red hives; swelling of the lips and eyelids; a hoarse voice; and audible expiratory wheezing. The client is anxious and says, "I feel like something terrible is happening." Vital signs: T 100.4°F (38°C), HR 128/min, RR 28/min, BP 78/42 mm Hg (on arrival: 122/76), SpO2 89% on room air.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set10-Case','RN Master Set 10 unfolding case study','A 42-year-old client weighing 80 kg is brought to the emergency department 1 hour after being burned in a house fire. There was no enclosed-space smoke exposure; the client was burned while pulling a family member from a burning porch. Nurses'' notes, 0300: Alert and oriented. Voice clear; no soot in the mouth or nose; no singed nasal hair. Burns cover the entire anterior trunk and the anterior surfaces of both legs. Some areas are red, blistered, moist, and very painful; other areas are white, dry, leathery, and painless to touch. Pedal pulses palpable bilaterally. Pain rated 9/10. Indwelling urinary catheter inserted: 15 mL of dark amber urine in the first hour. Vital signs: T 97.0°F (36.1°C), HR 128/min, RR 24/min, BP 96/60 mm Hg, SpO2 97% on room air. Laboratory results: hematocrit 54% (37–47), potassium 5.4 mEq/L (3.5–5.0), sodium 134 mEq/L (135–145).','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set11-Case','RN Master Set 11 unfolding case study','A 78-year-old client with heart failure takes furosemide 40 mg daily and digoxin 0.125 mg daily. The client has had nausea and vomiting for 3 days from viral gastroenteritis but kept taking the furosemide. The client is admitted from the emergency department. Nurses'' notes, 1100: Reports weakness, dizziness when standing, and leg cramps. Dry mucous membranes. Abdomen mildly distended with hypoactive bowel sounds. Voided 150 mL of dark amber urine since arrival 4 hours ago. Respirations shallow. Cardiac monitor shows sinus tachycardia with frequent premature ventricular contractions (PVCs) and prominent U waves. Vital signs: T 98.8°F (37.1°C). Lying: BP 108/64 mm Hg, HR 102/min. Standing: BP 86/50 mm Hg, HR 124/min, client reports near-fainting. RR 12/min. SpO2 95% on room air. Laboratory results: sodium 136 mEq/L, potassium 2.6 mEq/L (3.5–5.0), chloride 88 mEq/L (98–106), magnesium 1.4 mg/dL (1.7–2.2), BUN 38 mg/dL, creatinine 1.3 mg/dL (baseline 0.9). Arterial blood gas: pH 7.50, PaCO2 46 mm Hg, HCO3 34 mEq/L.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
insert into public.question_case_studies(id,title,case_stem,initial_data,source_note) values('RNMaster-Set12-Case','RN Master Set 12 unfolding case study','A 32-year-old client, now gravida 4 para 4, gave birth vaginally 45 minutes ago to a 4,200-g (9 lb 4 oz) newborn after an 18-hour labor augmented with oxytocin. The placenta delivered intact. The oxytocin infusion was stopped after delivery of the placenta. The client has initiated breastfeeding. Nurses'' notes, 1545: The client reports feeling dizzy and "a gush of blood." Perineal pad saturated in 15 minutes with several large clots. Fundus boggy, 2 cm above the umbilicus, and deviated to the right. Bladder palpable above the symphysis; the client has not voided since delivery. Skin pale and cool. Quantitative blood loss since birth: 950 mL. Vital signs: HR 118/min, BP 92/58 mm Hg (1 hour ago: 124/78), RR 22/min, SpO2 97% on room air, T 98.8°F (37.1°C). History: no hypertension, no asthma. Blood type O positive.','{}'::jsonb,'User-provided RN master case study.') on conflict(id) do update set case_stem=excluded.case_stem,updated_at=now();
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set02-RN-4','Physiological Adaptation','Tension pneumothorax','bow_tie','A client who was intubated after chest trauma becomes acutely agitated. The nurse notes absent breath sounds on the right, tracheal deviation to the left, distended neck veins, HR 134/min, BP 78/50 mm Hg, and SpO2 82% on FiO2 60%. Complete the diagram by choosing the condition the client is most likely experiencing, 2 actions the nurse should take, and 2 parameters the nurse should monitor.','','','Absent breath sounds on one side with tracheal deviation away from the affected side, JVD, and hypotension indicate tension pneumothorax, which obstructs venous return and requires immediate decompression. Tamponade does not cause tracheal deviation or unilateral absent breath sounds. Advancing the tube would worsen a right mainstem problem.','Respiratory','Adult Health','{"groups":[{"id":"g1","label":"Condition","choose":1,"options":[{"id":"g1o1","label":"Tension pneumothorax","correct":true},{"id":"g1o2","label":"Cardiac tamponade","correct":false},{"id":"g1o3","label":"Pulmonary embolism","correct":false},{"id":"g1o4","label":"Right mainstem intubation","correct":false}]},{"id":"g2","label":"Actions to take","choose":2,"options":[{"id":"g2o1","label":"Call for immediate provider/rapid response evaluation","correct":true},{"id":"g2o2","label":"Prepare for needle decompression followed by chest tube insertion","correct":true},{"id":"g2o3","label":"Administer a PRN sedative","correct":false},{"id":"g2o4","label":"Advance the endotracheal tube 2 cm","correct":false},{"id":"g2o5","label":"Obtain a sputum culture","correct":false}]},{"id":"g3","label":"Parameters to monitor","choose":2,"options":[{"id":"g3o1","label":"Oxygen saturation","correct":true},{"id":"g3o2","label":"Blood pressure and heart rate","correct":true},{"id":"g3o3","label":"Urine specific gravity","correct":false},{"id":"g3o4","label":"Blood glucose","correct":false},{"id":"g3o5","label":"Serum sodium","correct":false}]}]}','','0'),
('Set02-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','leukocytosis indicate acute deterioration and infection. Barrel chest and clubbing are chronic findings in COPD and are not new.','Respiratory','Adult Health','{"segments":[{"id":"s1","text":"Tripod position with accessory muscle use","correct":true},{"id":"s2","text":"Barrel chest","correct":false},{"id":"s3","text":"Clubbing of the fingers","correct":false},{"id":"s4","text":"RR 30/min","correct":false},{"id":"s5","text":"SpO2 84% on room air","correct":true},{"id":"s6","text":"T 101.3°F (38.5°C)","correct":false},{"id":"s7","text":"pH 7.31 and PaCO2 62 mm Hg","correct":true},{"id":"s8","text":"WBC 15,800/mm3","correct":false}]}','RNMaster-Set02-Case','1'),
('Set02-RN-21','Reduction of Risk Potential','Case study: Analyze cues','cloze_dropdown','Complete the sentence by choosing from the lists of options. Compared with the client''s baseline, the current ABG shows ___1___ that is ___2___.','','','compensated The pH is below 7.35 with an elevated PaCO2 (respiratory cause). The HCO3 is elevated from chronic renal compensation but has not normalized the pH, so the disorder is partially compensated. The acute rise in PaCO2 above baseline (62 vs. 50) reflects an acute-on-chronic process.','Respiratory','Adult Health','{"blanks":[{"id":"b1","options":["respiratory acidosis","metabolic acidosis","respiratory alkalosis","metabolic alkalosis"],"correct":"respiratory acidosis"},{"id":"b2","options":["partially compensated","fully compensated","uncompensated"],"correct":"partially compensated"}]}','RNMaster-Set02-Case','2'),
('Set02-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___ triggered by ___2___.','','','pneumonia Increased dyspnea and purulent sputum with fever, leukocytosis, localized crackles, and a lobar infiltrate point to pneumonia causing a COPD exacerbation. There are no findings of fluid overload, and the infiltrate and gradual onset argue against PE or pneumothorax.','Respiratory','Adult Health','{"blanks":[{"id":"b1","options":["an acute exacerbation of COPD","acute decompensated heart failure","a pulmonary embolism","a spontaneous pneumothorax"],"correct":"an acute exacerbation of COPD"},{"id":"b2","options":["bacterial pneumonia","fluid overload","deep vein thrombosis","oxygen toxicity"],"correct":"bacterial pneumonia"}]}','RNMaster-Set02-Case','3'),
('Set02-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','On day 3, the nurse reassesses the client. For each finding, indicate whether it shows improvement or no improvement.','','','Improved: ABG near baseline, RR 20 without accessory muscles, thin white sputum, SpO2 90% on 2 L. Not improved: T 100.9°F, WBC 16,400. Return of the ABG toward baseline, decreased work of breathing, clearing sputum, and SpO2 in the target range show response. Persistent fever and rising WBC suggest the infection is not responding, so the antibiotic regimen may need to change. Answers: Set 3: Neurological System','Respiratory','Adult Health','{"columns":[{"id":"c1","label":"Improved"},{"id":"c2","label":"Not improved"}],"rows":[{"id":"r1","label":"pH 7.36, PaCO2 52 mm Hg","correct":"c2"},{"id":"r2","label":"RR 20/min without accessory muscle use","correct":"c1"},{"id":"r3","label":"T 100.9°F (38.3°C)","correct":"c1"},{"id":"r4","label":"Sputum changed to thin and white","correct":"c1"},{"id":"r5","label":"SpO2 90% on 2 L/min nasal cannula","correct":"c1"},{"id":"r6","label":"WBC 16,400/mm3","correct":"c1"}]}','RNMaster-Set02-Case','6'),
('Set03-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the 1600 findings that require immediate follow-up.','','','bradycardia, irregular respirations) indicate rapidly rising ICP and possible herniation. The arm and wrist injuries need care but are not immediately life-threatening.','Neurologic','Adult Health','{"segments":[{"id":"s1","text":"Increasingly drowsy","correct":false},{"id":"s2","text":"Vomited twice in 20 minutes","correct":false},{"id":"s3","text":"Opens eyes only to painful stimuli","correct":true},{"id":"s4","text":"Right pupil 6 mm and sluggish","correct":true},{"id":"s5","text":"BP 168/70 mm Hg","correct":false},{"id":"s6","text":"HR 54/min","correct":false},{"id":"s7","text":"RR 10/min and irregular","correct":true},{"id":"s8","text":"Abrasions on the right forearm","correct":true},{"id":"s9","text":"Swelling of the left wrist","correct":false}]}','RNMaster-Set03-Case','1'),
('Set03-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is consistent with increased intracranial pressure or unrelated to it.','','','Increased ICP: pupil changes, widened pulse pressure, bradycardia, vomiting. Unrelated: wrist deformity, abrasions. Compression of cranial nerve III causes ipsilateral pupil dilation. Widened pulse pressure and bradycardia are part of Cushing''s response, and vomiting results from pressure on the medullary vomiting center. The musculoskeletal and skin injuries are separate problems.','Neurologic','Adult Health','{"columns":[{"id":"c1","label":"Increased ICP"},{"id":"c2","label":"Unrelated"}],"rows":[{"id":"r1","label":"Right pupil dilated and sluggish","correct":"c2"},{"id":"r2","label":"Pulse pressure widened from 50 to 98 mm Hg","correct":"c1"},{"id":"r3","label":"Heart rate decreased from 88 to 54/min","correct":"c1"},{"id":"r4","label":"Repeated vomiting","correct":"c1"},{"id":"r5","label":"Deformity of the left wrist","correct":"c1"},{"id":"r6","label":"Abrasions on the right forearm","correct":"c1"}]}','RNMaster-Set03-Case','2'),
('Set03-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___, as evidenced by ___2___.','','','brief loss of consciousness followed by a lucid interval and rapid deterioration Epidural hematomas are usually arterial bleeds (often from the middle meningeal artery) that classically cause a brief LOC, a lucid interval, then rapid decline. Chronic subdural hematomas develop over weeks, and a concussion does not cause focal pupil changes.','Neurologic','Adult Health','{"blanks":[{"id":"b1","options":["an epidural hematoma","a concussion","a chronic subdural hematoma","bacterial meningitis"],"correct":"an epidural hematoma"},{"id":"b2","options":["a brief loss of consciousness followed by a lucid interval and rapid deterioration","gradual confusion developing over several weeks","fever with nuchal rigidity","full recovery within hours"],"correct":"a brief loss of consciousness followed by a lucid interval and rapid deterioration"}]}','RNMaster-Set03-Case','3'),
('Set03-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate for this client? Select all that apply. ☐','Prepare the client for emergency head CT and possible craniotomy ☐|Elevate the head of the bed 30 degrees with the head midline ☐|Administer mannitol or hypertonic saline as prescribed ☐|Perform a lumbar puncture to measure pressure ☐|Infuse D5W at a rapid rate ☐|Perform neurological checks every 15 minutes ☐|Prepare for airway protection if GCS continues to decline','A,B,C,F,G','An expanding epidural hematoma requires emergency surgical evacuation. Head elevation and osmotic therapy reduce ICP while frequent neuro checks track status, and airway protection is needed as consciousness falls. Lumbar puncture with high ICP can cause herniation, and hypotonic fluids such as D5W worsen cerebral edema.','Neurologic','Management of Care','{}','RNMaster-Set03-Case','4'),
('Set03-RN-24','Management of Care','Case study: Take action','single_best_answer','At 1600, what should the nurse do first?','Repeat the neurological assessment in 1 hour|Notify the provider immediately and call for emergency support|Administer the prescribed PRN analgesic for headache|Place the client flat to improve cerebral blood flow','B','Rapid neurological deterioration with signs of herniation is an emergency requiring immediate provider notification. Waiting delays surgery, opioids can mask neurological changes and depress respirations, and a flat position increases ICP.','Neurologic','Management of Care','{}','RNMaster-Set03-Case','5'),
('Set03-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','The client undergoes evacuation of the hematoma. On postoperative day 1, the nurse reassesses. For each finding, indicate whether it indicates the client is progressing as expected or requires follow-up. Progressing   Requires Finding','','','As expected: GCS 14, equal reactive pupils, ICP 12. Follow-up: CPP 52, glucose-positive nasal drainage, large dilute urine output. Improved GCS, normal pupils, and an ICP within 5–15 mm Hg show recovery. A CPP below the usual goal of 60–70 mm Hg risks cerebral ischemia. Glucose-positive clear drainage suggests a CSF leak, and large volumes of dilute urine suggest diabetes insipidus. Answers: Set 4: Endocrine System','Neurologic','Adult Health','{"columns":[{"id":"c1","label":"follow-up"}],"rows":[{"id":"r1","label":"GCS 14","correct":"c1"},{"id":"r2","label":"Pupils 3 mm, equal, and reactive","correct":"c1"},{"id":"r3","label":"ICP 12 mm Hg","correct":"c1"},{"id":"r4","label":"Cerebral perfusion pressure 52 mm Hg","correct":"c1"},{"id":"r5","label":"Clear nasal drainage that tests positive for glucose","correct":"c1"},{"id":"r6","label":"Urine output 3,200 mL over 4 hours with low specific gravity","correct":"c1"}]}','RNMaster-Set03-Case','6'),
('Set04-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','metabolic acidosis, and abnormal potassium all require urgent treatment. The low-grade temperature and normal SpO2 are not immediate concerns.','Endocrine','Adult Health','{"segments":[{"id":"s1","text":"Lethargic but arousable","correct":false},{"id":"s2","text":"RR 32/min and deep","correct":true},{"id":"s3","text":"BP 94/56 mm Hg","correct":false},{"id":"s4","text":"HR 124/min","correct":false},{"id":"s5","text":"Temperature 99.8°F","correct":false},{"id":"s6","text":"Glucose 486 mg/dL","correct":true},{"id":"s7","text":"pH 7.18 and HCO3 10 mEq/L","correct":true},{"id":"s8","text":"Potassium 5.6 mEq/L","correct":true},{"id":"s9","text":"SpO2 99% on room air","correct":false}]}','RNMaster-Set04-Case','1'),
('Set04-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is primarily caused by osmotic diuresis or by ketoacidosis. Osmotic','','','Ketoacidosis: Kussmaul respirations, fruity breath, low HCO3. Osmotic diuresis: dry membranes/poor turgor, hypotension/tachycardia, polyuria/thirst. Hyperglycemia pulls water into the urine, causing polyuria, dehydration, and hypovolemia. Ketone accumulation causes metabolic acidosis, compensatory Kussmaul respirations to blow off CO2, and acetone breath.','Endocrine','Adult Health','{"columns":[{"id":"c1","label":"Ketoacidosis"}],"rows":[{"id":"r1","label":"Deep, rapid respirations","correct":"c1"},{"id":"r2","label":"Fruity breath odor","correct":"c1"},{"id":"r3","label":"Dry mucous membranes and poor skin turgor","correct":"c1"},{"id":"r4","label":"Hypotension and tachycardia","correct":"c1"},{"id":"r5","label":"Polyuria and extreme thirst","correct":"c1"},{"id":"r6","label":"HCO3 of 10 mEq/L","correct":"c1"}]}','RNMaster-Set04-Case','2'),
('Set04-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentences by choosing from the lists of options. The client''s ABG shows ___1___. The nurse must monitor potassium closely because ___2___.','','','therapy will shift potassium into the cells and can cause hypokalemia The low pH and low HCO3 indicate metabolic acidosis, and the low PaCO2 shows respiratory compensation that has not normalized the pH. Although serum potassium is high (acidosis and insulin deficiency shift it out of cells), total body potassium is depleted from diuresis. Insulin drives potassium back into cells and can cause dangerous hypokalemia.','Endocrine','Adult Health','{"blanks":[{"id":"b1","options":["partially compensated metabolic acidosis","uncompensated respiratory acidosis","fully compensated metabolic alkalosis","partially compensated respiratory alkalosis"],"correct":"partially compensated metabolic acidosis"},{"id":"b2","options":["insulin therapy will shift potassium into the cells and can cause hypokalemia","the client''s kidneys are retaining potassium","potassium will rise further when fluids are given","vomiting always causes hyperkalemia"],"correct":"insulin therapy will shift potassium into the cells and can cause hypokalemia"}]}','RNMaster-Set04-Case','3'),
('Set04-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which prescriptions does the nurse anticipate for this client? Select all that apply. ☐','0.9% sodium chloride IV bolus ☐|Continuous IV regular insulin infusion once potassium is confirmed to be at least 3.3 mEq/L ☐|Hourly blood glucose monitoring ☐|Continuous cardiac monitoring ☐|Add potassium to IV fluids once the level falls below about 5.0–5.2 mEq/L and urine output is adequate ☐|Sodium bicarbonate IV for a pH of 7.18 ☐|Insulin glargine subcutaneously as the only insulin','A,B,C,D,E','DKA treatment includes isotonic fluid resuscitation, IV regular insulin, hourly glucose checks, cardiac monitoring for potassium-related dysrhythmias, and potassium replacement as levels fall. Bicarbonate is generally reserved for a pH below about 6.9–7.0. Long-acting subcutaneous insulin alone is too slow and unpredictable in DKA.','Endocrine','Pharmacology','{}','RNMaster-Set04-Case','4'),
('Set04-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','IV access has been established. Which prescription should the nurse implement first?','Regular insulin 0.1 unit/kg IV bolus|0.9% sodium chloride 1 L IV over 1 hour|Potassium chloride 20 mEq added to the IV fluid|Sodium bicarbonate 50 mEq IV push','B','Fluid replacement is the first priority. It restores perfusion, lowers glucose by dilution, and improves renal clearance of ketones. Insulin follows once potassium is confirmed adequate, and potassium is not added while the level is above 5.2 mEq/L.','Endocrine','Adult Health','{}','RNMaster-Set04-Case','5'),
('Set04-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Ten hours after admission, the nurse reviews the client''s status. For each finding, indicate whether it shows the client is improving or requires further intervention. Requires','','','Improving: anion gap 11, pH 7.34, HR 94 and BP 118/72, alert and hungry, urine output 60 mL/hr. Requires intervention: potassium 3.2. A closed anion gap, near-normal pH, stable vital signs, improved mental status, and adequate urine output show DKA is resolving. Hypokalemia requires replacement and cardiac monitoring. Once the client can eat, subcutaneous basal insulin is given 1–2 hours before the insulin infusion is stopped. Answers: Set 5: Renal and Genitourinary System','Endocrine','Adult Health','{"columns":[{"id":"c1","label":"Improving"}],"rows":[{"id":"r1","label":"Anion gap 11","correct":"c1"},{"id":"r2","label":"Arterial pH 7.34","correct":"c1"},{"id":"r3","label":"Potassium 3.2 mEq/L","correct":"c1"},{"id":"r4","label":"HR 94/min, BP 118/72 mm Hg","correct":"c1"},{"id":"r5","label":"Alert and asking for something to eat","correct":"c1"},{"id":"r6","label":"Urine output 60 mL/hr","correct":"c1"}]}','RNMaster-Set04-Case','6'),
('Set05-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','with crackles reflects fluid overload. A thrill and bruit mean the fistula is working. The hemoglobin is typical for ESKD and not an emergency.','Renal & Urinary','Adult Health','{"segments":[{"id":"s1","text":"Potassium 7.2 mEq/L","correct":true},{"id":"s2","text":"Peaked T waves and widened QRS","correct":true},{"id":"s3","text":"HR 54/min and irregular","correct":true},{"id":"s4","text":"SpO2 91% on room air","correct":true},{"id":"s5","text":"Crackles in both lung bases","correct":true},{"id":"s6","text":"Palpable thrill and audible bruit in the fistula","correct":false},{"id":"s7","text":"Temperature 98.2°F","correct":false},{"id":"s8","text":"Hemoglobin 9.1 g/dL","correct":false}]}','RNMaster-Set05-Case','1'),
('Set05-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is primarily related to hyperkalemia or to fluid volume excess. Fluid volume','','','Hyperkalemia: peaked T waves, muscle weakness, paresthesias. Fluid excess: crackles, weight gain, hypertension. High potassium alters cardiac and neuromuscular membrane excitability, causing ECG changes, weakness, and paresthesias. Missed dialysis in an anuric client leads to fluid retention with pulmonary congestion, weight gain, and hypertension.','Renal & Urinary','Adult Health','{"columns":[{"id":"c1","label":"Hyperkalemia"}],"rows":[{"id":"r1","label":"Peaked T waves","correct":"c1"},{"id":"r2","label":"Generalized muscle weakness","correct":"c1"},{"id":"r3","label":"Tingling in the hands","correct":"c1"},{"id":"r4","label":"Crackles in the lung bases","correct":"c1"},{"id":"r5","label":"Weight 4.2 kg above dry weight","correct":"c1"},{"id":"r6","label":"BP 172/98 mm Hg","correct":"c1"}]}','RNMaster-Set05-Case','2'),
('Set05-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The most immediate threat to the client''s life is ___1___ caused by ___2___.','','','potassium of 7.2 mEq/L with a widened QRS can rapidly progress to ventricular fibrillation or asystole. Fluid overload is serious but secondary in immediacy, and the hypocalcemia and hyperphosphatemia are chronic CKD findings.','Renal & Urinary','Adult Health','{"blanks":[{"id":"b1","options":["a lethal cardiac dysrhythmia","a seizure","a stroke","fistula thrombosis"],"correct":"a lethal cardiac dysrhythmia"},{"id":"b2","options":["hyperkalemia","hypocalcemia","hyperphosphatemia","anemia"],"correct":"hyperkalemia"}]}','RNMaster-Set05-Case','3'),
('Set05-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which prescriptions does the nurse anticipate for this client? Select all that apply. ☐','Calcium gluconate IV ☐|Regular insulin IV with dextrose ☐|Nebulized albuterol ☐|Emergency hemodialysis ☐|Continuous cardiac monitoring ☐|Spironolactone PO ☐|0.9% sodium chloride 2 L IV bolus','A,B,C,D,E','Calcium stabilizes the cardiac membrane. Insulin with dextrose and albuterol shift potassium into cells. Dialysis removes potassium and excess fluid, and continuous monitoring is essential. Spironolactone raises potassium, and a fluid bolus would worsen overload in an anuric client.','Renal & Urinary','Pharmacology','{}','RNMaster-Set05-Case','4'),
('Set05-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','Which medication should the nurse administer first?','Regular insulin 10 units IV with dextrose 50%|Calcium gluconate IV|Nebulized albuterol|Sodium polystyrene sulfonate orally','B','With ECG changes present, calcium is given first because it protects the heart within minutes. It does not lower potassium, so insulin with dextrose and other treatments follow. Oral binders act too slowly for an emergency.','Renal & Urinary','Pharmacology','{}','RNMaster-Set05-Case','5'),
('Set05-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','The client completes emergency hemodialysis. For each finding, indicate whether it shows effective treatment or requires follow-up. Requires','','','Effective: K 4.6, normal ECG, weight down 3.8 kg, SpO2 97%. Follow-up: headache/nausea/restlessness, glucose 54. Normalized potassium and ECG, fluid removal, and improved oxygenation show success. Headache, nausea, and restlessness suggest dialysis disequilibrium syndrome from rapid solute shifts. Hypoglycemia can follow insulin treatment for hyperkalemia, especially in kidney failure, which prolongs insulin action. Answers: Set 6: Gastrointestinal System and Nutrition','Renal & Urinary','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Potassium 4.6 mEq/L","correct":"c1"},{"id":"r2","label":"Normal T waves and narrow QRS","correct":"c1"},{"id":"r3","label":"Weight decreased by 3.8 kg","correct":"c1"},{"id":"r4","label":"SpO2 97% on room air","correct":"c1"},{"id":"r5","label":"Blood glucose 54 mg/dL","correct":"c1"}]}','RNMaster-Set05-Case','6'),
('Set06-RN-13','Physiological Adaptation','Inflammatory bowel disease','matrix_grid','For each characteristic, indicate whether it is more typical of Crohn''s disease or ulcerative colitis. Crohn''s   Ulcerative Finding','','','Crohn''s: skip lesions, fistulas, transmural inflammation. UC: continuous from rectum, bloody diarrhea, curable by colectomy. Crohn''s can affect any part of the GI tract with transmural, patchy inflammation that leads to fistulas and strictures. Ulcerative colitis is limited to the colon mucosa, starts in the rectum, spreads continuously, and causes bloody diarrhea. Removing the colon cures UC.','Gastrointestinal','Adult Health','{"columns":[{"id":"c1","label":"colitis"}],"rows":[{"id":"r1","label":"\"Skip lesions\" with areas of normal bowel between","correct":"c1"},{"id":"r2","label":"Continuous inflammation beginning in the rectum","correct":"c1"},{"id":"r3","label":"Fistula formation","correct":"c1"},{"id":"r4","label":"Frequent bloody diarrhea","correct":"c1"},{"id":"r5","label":"Inflammation through all layers of the bowel wall","correct":"c1"},{"id":"r6","label":"Often cured by total colectomy","correct":"c1"}]}','','0'),
('Set06-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Tachycardia, hypotension, poor peripheral perfusion, and a low hemoglobin indicate significant blood loss and shock. Normal platelets and INR mean coagulopathy is not contributing, and a soft abdomen argues against perforation.','Gastrointestinal','Adult Health','{"segments":[{"id":"s1","text":"HR 122/min","correct":false},{"id":"s2","text":"BP 88/52 mm Hg","correct":false},{"id":"s3","text":"Skin cool and clammy","correct":true},{"id":"s4","text":"Capillary refill 4 seconds","correct":true},{"id":"s5","text":"Hemoglobin 7.2 g/dL","correct":true},{"id":"s6","text":"Platelets 240,000/mm3","correct":false},{"id":"s7","text":"INR 1.1","correct":false},{"id":"s8","text":"Abdomen soft and nondistended","correct":false}]}','RNMaster-Set06-Case','1'),
('Set06-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects the body''s compensatory response to blood loss or is a direct result of upper GI bleeding. Compensatory   Direct result Finding','','','Compensatory: tachycardia, cool clammy skin, tachypnea. Direct result: melena, coffee-ground emesis, elevated BUN with normal creatinine. Sympathetic activation increases heart rate, constricts peripheral vessels, and increases respirations to maintain oxygen delivery. Blood partially digested by gastric acid appears as coffee grounds or melena, and absorption of digested blood proteins raises BUN.','Gastrointestinal','Adult Health','{"columns":[{"id":"c1","label":"of GI bleeding"}],"rows":[{"id":"r1","label":"Tachycardia","correct":"c1"},{"id":"r2","label":"Cool, clammy skin","correct":"c1"},{"id":"r3","label":"Tachypnea","correct":"c1"},{"id":"r4","label":"Black, tarry stools","correct":"c1"},{"id":"r5","label":"Coffee-ground emesis","correct":"c1"},{"id":"r6","label":"Elevated BUN with a normal creatinine","correct":"c1"}]}','RNMaster-Set06-Case','2'),
('Set06-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___ caused by ___2___.','','','bleeding peptic ulcer associated with NSAID use Chronic high-dose ibuprofen damages the gastric mucosa and causes ulcers. Melena and coffee-ground emesis indicate an upper GI source, and hemodynamic instability with a low hemoglobin reflects hypovolemic shock. There is no history of liver disease or fever.','Gastrointestinal','Adult Health','{"blanks":[{"id":"b1","options":["hypovolemic shock","septic shock","cardiogenic shock","anaphylactic shock"],"correct":"hypovolemic shock"},{"id":"b2","options":["a bleeding peptic ulcer associated with NSAID use","ruptured esophageal varices from cirrhosis","acute pancreatitis","diverticular bleeding"],"correct":"a bleeding peptic ulcer associated with NSAID use"}]}','RNMaster-Set06-Case','3'),
('Set06-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Insert two large-bore IV catheters ☐|Infuse isotonic crystalloid solution ☐|Type and crossmatch for packed red blood cells ☐|Administer an IV proton pump inhibitor ☐|Prepare the client for upper endoscopy ☐|Keep the client NPO ☐|Administer ibuprofen for the epigastric pain','A,B,C,D,E,F','Management includes large-bore access, fluid resuscitation, transfusion (commonly when hemoglobin is below 7–8 g/dL or the client is unstable), IV PPI to stabilize clots, and endoscopy to find and treat the bleeding. The client stays NPO for the procedure. NSAIDs caused the bleeding and are stopped.','Gastrointestinal','Management of Care','{}','RNMaster-Set06-Case','4'),
('Set06-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Obtain informed consent for endoscopy|Insert two large-bore IV catheters and begin isotonic fluids|Collect a stool specimen for occult blood|Complete a detailed medication history','B','Restoring circulating volume is the priority in hypovolemic shock. The airway is currently intact. Consent and history follow, and the stool is already visibly bloody, so occult blood testing adds nothing.','Gastrointestinal','Adult Health','{}','RNMaster-Set06-Case','5'),
('Set06-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','The client receives 2 units of packed red blood cells, and a bleeding ulcer is cauterized during endoscopy. Six hours later, the nurse reassesses. For each finding, indicate whether it shows improvement or no improvement.','','','Improved: HR 92, BP 118/70, Hgb 9.0, urine output 45 mL/hr, warm dry skin. Not improved: large maroon stool with new dizziness. Stable vital signs, adequate urine output, improved perfusion, and an expected hemoglobin rise (about 1 g/dL per unit) show a response. A new large bloody stool with dizziness suggests rebleeding and requires immediate reporting. Answers: Set 7: Musculoskeletal System','Gastrointestinal','Adult Health','{"columns":[{"id":"c1","label":"Improved"},{"id":"c2","label":"Not improved"}],"rows":[{"id":"r1","label":"HR 92/min","correct":"c2"},{"id":"r2","label":"BP 118/70 mm Hg","correct":"c1"},{"id":"r3","label":"Hemoglobin 9.0 g/dL","correct":"c1"},{"id":"r4","label":"Urine output 45 mL/hr","correct":"c1"},{"id":"r5","label":"Large maroon stool with new dizziness","correct":"c1"},{"id":"r6","label":"Skin warm and dry","correct":"c1"}]}','RNMaster-Set06-Case','6'),
('Set07-RN-12','Physiological Adaptation','Arthritis','matrix_grid','For each characteristic, indicate whether it is more typical of rheumatoid arthritis or osteoarthritis. Rheumatoid','','','RA: prolonged morning stiffness, symmetric small-joint involvement, systemic symptoms. OA: Heberden''s nodes, activity-related pain, brief stiffness. RA is a systemic autoimmune disease causing symmetric synovitis with prolonged stiffness and systemic symptoms. OA is degenerative, affecting weight-bearing joints and distal finger joints, with pain related to use.','Musculoskeletal','Adult Health','{"columns":[{"id":"c1","label":"Osteoarthritis"}],"rows":[{"id":"r1","label":"Morning stiffness lasting more than 1 hour","correct":"c1"},{"id":"r2","label":"Symmetric involvement of small joints of the hands","correct":"c1"},{"id":"r3","label":"Heberden''s nodes on the distal finger joints","correct":"c1"},{"id":"r4","label":"Fatigue, low-grade fever, and weight loss","correct":"c1"},{"id":"r5","label":"Pain that worsens with activity and improves with rest","correct":"c1"},{"id":"r6","label":"Morning stiffness lasting less than 30 minutes","correct":"c1"}]}','','0'),
('Set07-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','platelets are new, serious findings. Moderate fracture pain and clear pin-site drainage are expected.','Musculoskeletal','Adult Health','{"segments":[{"id":"s1","text":"Newly restless and confused","correct":false},{"id":"s2","text":"Petechiae on the chest, axillae, and conjunctivae","correct":true},{"id":"s3","text":"SpO2 86% on room air","correct":true},{"id":"s4","text":"RR 30/min","correct":false},{"id":"s5","text":"HR 124/min","correct":false},{"id":"s6","text":"T 101.2°F","correct":false},{"id":"s7","text":"Platelets 98,000/mm3","correct":true},{"id":"s8","text":"Fracture-site pain 5/10","correct":false},{"id":"s9","text":"Clear, crusted pin-site drainage","correct":false}]}','RNMaster-Set07-Case','1'),
('Set07-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it is consistent with fat embolism syndrome or expected after a femur fracture. Expected Fat embolism','','','FES: petechiae, acute confusion, hypoxemia, falling platelets. Expected: thigh swelling, fracture-site pain. Fat embolism syndrome classically causes a triad of respiratory distress, neurological changes, and petechial rash, typically 24–72 hours after long-bone fractures. Thrombocytopenia is common. Swelling and pain at the fracture site are expected.','Musculoskeletal','Adult Health','{"columns":[{"id":"c1","label":"after femur"}],"rows":[{"id":"r1","label":"Petechiae in the axillae and on the conjunctivae","correct":"c1"},{"id":"r2","label":"Acute confusion","correct":"c1"},{"id":"r3","label":"SpO2 86% on room air","correct":"c1"},{"id":"r4","label":"Swelling of the left thigh","correct":"c1"},{"id":"r5","label":"Moderate pain at the fracture site","correct":"c1"},{"id":"r6","label":"Platelet count decrease","correct":"c1"}]}','RNMaster-Set07-Case','2'),
('Set07-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentences by choosing from the lists of options. The client is most likely experiencing ___1___. The priority problem is ___2___.','','','gas exchange The timing, petechiae, confusion, and hypoxemia after a long-bone fracture point to fat embolism syndrome. Distal perfusion is intact, which argues against compartment syndrome, and BP is stable, which argues against hypovolemic shock. Hypoxemia is the most immediate threat.','Musculoskeletal','Adult Health','{"blanks":[{"id":"b1","options":["fat embolism syndrome","compartment syndrome","osteomyelitis","hypovolemic shock"],"correct":"fat embolism syndrome"},{"id":"b2","options":["impaired gas exchange","acute pain","risk for infection","impaired physical mobility"],"correct":"impaired gas exchange"}]}','RNMaster-Set07-Case','3'),
('Set07-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate for this client? Select all that apply. ☐','Administer high-flow oxygen ☐|Elevate the head of the bed ☐|Prepare for possible intubation and mechanical ventilation ☐|Minimize movement of the fractured leg ☐|Perform frequent neurological assessments ☐|Begin active range-of-motion exercises of the left leg ☐|Increase the traction weight to realign the bone','A,B,C,D,E','Treatment for fat embolism syndrome is supportive: oxygenation, positioning, ventilatory support if needed, and neurological monitoring. Minimizing fracture movement and early stabilization reduce further fat release. Moving the fracture or changing traction without a prescription can worsen embolization.','Musculoskeletal','Management of Care','{}','RNMaster-Set07-Case','4'),
('Set07-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Obtain a portable chest x-ray|Apply high-flow oxygen and raise the head of the bed|Draw blood for arterial blood gases|Document the petechiae with a photograph','B','Correcting hypoxemia is the immediate priority. The nurse applies oxygen per protocol while calling for the provider or rapid response team. Diagnostic tests follow once oxygenation is supported.','Musculoskeletal','Adult Health','{}','RNMaster-Set07-Case','5'),
('Set07-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Forty-eight hours later, the nurse reassesses the client. For each finding, indicate whether it shows improvement or no improvement.','','','Improved: SpO2 95% on 4 L, oriented, RR 20, petechiae fading. Not improved: platelets 86,000, new crackles with rising oxygen needs. Better oxygenation, orientation, respiratory rate, and fading rash show improvement. Falling platelets and new crackles with rising oxygen requirements suggest ongoing lung injury, possibly progressing to ARDS. Answers: Set 8: Hematology and Oncology','Musculoskeletal','Adult Health','{"columns":[{"id":"c1","label":"Improved"},{"id":"c2","label":"Not improved"}],"rows":[{"id":"r1","label":"SpO2 95% on 4 L/min nasal cannula","correct":"c2"},{"id":"r2","label":"Oriented to person, place, and time","correct":"c1"},{"id":"r3","label":"RR 20/min","correct":"c1"},{"id":"r4","label":"Petechiae fading","correct":"c1"},{"id":"r5","label":"Platelets 86,000/mm3","correct":"c1"},{"id":"r6","label":"New bilateral crackles with increasing oxygen requirements","correct":"c1"}]}','RNMaster-Set07-Case','6'),
('Set08-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Fever in severe neutropenia is a medical emergency. Tachycardia, a falling BP, and elevated lactate suggest sepsis with hypoperfusion, and the PICC site is a likely source. SpO2 is acceptable, and fatigue is expected with anemia.','Hematologic','Adult Health','{"segments":[{"id":"s1","text":"T 101.5°F (38.6°C)","correct":false},{"id":"s2","text":"Shaking chills","correct":true},{"id":"s3","text":"HR 118/min","correct":false},{"id":"s4","text":"BP 96/58 mm Hg","correct":false},{"id":"s5","text":"Redness and tenderness around the PICC site","correct":true},{"id":"s6","text":"ANC 200/mm³","correct":false},{"id":"s7","text":"Lactate 2.8 mmol/L","correct":true},{"id":"s8","text":"SpO2 95% on room air","correct":false},{"id":"s9","text":"Reports fatigue","correct":false}]}','RNMaster-Set08-Case','1'),
('Set08-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate whether it primarily reflects infection/sepsis, low platelets (thrombocytopenia), or anemia.','','','Infection/sepsis: fever, PICC redness, lactate. Thrombocytopenia: petechiae, gum bleeding. Anemia: pallor and fatigue. Chemotherapy suppresses all bone marrow lines. Neutropenia causes infection risk, low platelets cause bleeding, and low hemoglobin causes fatigue and pallor. Lactate reflects tissue hypoperfusion from sepsis.','Hematologic','Adult Health','{"columns":[{"id":"c1","label":"Infection/sepsis"},{"id":"c2","label":"Low platelets"},{"id":"c3","label":"Anemia"}],"rows":[{"id":"r1","label":"Temperature 101.5°F","correct":"c1"},{"id":"r2","label":"Redness at the PICC site","correct":"c1"},{"id":"r3","label":"Lactate 2.8 mmol/L","correct":"c1"},{"id":"r4","label":"Petechiae on the lower legs","correct":"c1"},{"id":"r5","label":"Gum bleeding during mouth care","correct":"c1"},{"id":"r6","label":"Pallor and fatigue","correct":"c1"}]}','RNMaster-Set08-Case','2'),
('Set08-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is most likely experiencing ___1___, with the most likely source being ___2___.','','','Redness and tenderness at the central line insertion site point to a catheter-related bloodstream infection. Classic signs of infection may be muted in neutropenia.','Hematologic','Adult Health','{"blanks":[{"id":"b1","options":["febrile neutropenia with sepsis","a transfusion reaction","tumor lysis syndrome","a drug fever"],"correct":"febrile neutropenia with sepsis"},{"id":"b2","options":["the PICC line","the oral ulcers","the petechiae","a urinary tract infection"],"correct":"the PICC line"}]}','RNMaster-Set08-Case','3'),
('Set08-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Obtain blood cultures from the PICC and a peripheral site ☐|Start broad-spectrum IV antibiotics within 1 hour ☐|Administer an isotonic IV fluid bolus as prescribed ☐|Repeat the lactate level ☐|Maintain neutropenic precautions ☐|Take a rectal temperature every 2 hours ☐|Withhold antibiotics until culture results return','A,B,C,D,E','Febrile neutropenia requires cultures from each lumen and a peripheral site, then broad-spectrum antibiotics within 60 minutes. Fluids treat hypoperfusion, and repeat lactate tracks response. Rectal temperatures are avoided, and delaying antibiotics increases mortality.','Hematologic','Management of Care','{}','RNMaster-Set08-Case','4'),
('Set08-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The provider has written all prescriptions. Which action should the nurse take first?','Administer acetaminophen for the fever|Obtain the blood cultures|Administer the broad-spectrum IV antibiotic|Send the PICC tip for culture','B','Blood cultures are drawn immediately before antibiotics so the organism can be identified, but antibiotics must not be delayed beyond 60 minutes. The PICC is not removed until the provider decides, and acetaminophen is a lower priority.','Hematologic','Pharmacology','{}','RNMaster-Set08-Case','5'),
('Set08-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twenty-four hours later, the nurse reassesses the client. For each finding, indicate whether it shows improvement or no improvement.','','','Improved: T 99.1°F, BP 118/70, lactate 1.4, HR 90. Not improved: rigors after PICC flush, urine output 20 mL/hr. Improved temperature, BP, heart rate, and lactate show response to therapy. Rigors after flushing suggest bacteria seeding from the catheter, which may need to be removed. Low urine output suggests ongoing hypoperfusion or acute kidney injury. Answers: Set 9: Immune System and Infectious Disease','Hematologic','Adult Health','{"columns":[{"id":"c1","label":"Improved"},{"id":"c2","label":"Not improved"}],"rows":[{"id":"r1","label":"T 99.1°F (37.3°C)","correct":"c2"},{"id":"r2","label":"BP 118/70 mm Hg","correct":"c1"},{"id":"r3","label":"Lactate 1.4 mmol/L","correct":"c1"},{"id":"r4","label":"HR 90/min","correct":"c1"},{"id":"r5","label":"Rigors immediately after the PICC is flushed","correct":"c1"},{"id":"r6","label":"Urine output 20 mL/hr for the past 3 hours","correct":"c1"}]}','RNMaster-Set08-Case','6'),
('Set09-RN-2','Safety and Infection Control','Transmission-based precautions','matrix_grid','For each infection, indicate the transmission-based precautions required in addition to standard precautions.','','','Airborne: measles, TB. Droplet: influenza, pertussis. Contact: MRSA wound, scabies. Airborne pathogens remain suspended in the air and require a negative-pressure room and N95 respirator. Droplet pathogens travel short distances and require a surgical mask. Contact pathogens spread by direct or indirect touch and require a gown and gloves. Varicella requires both airborne and contact precautions.','Immune','Safety & Infection Control','{"columns":[{"id":"c1","label":"Airborne"},{"id":"c2","label":"Droplet"},{"id":"c3","label":"Contact"}],"rows":[{"id":"r1","label":"Measles (rubeola)","correct":"c1"},{"id":"r2","label":"Pulmonary tuberculosis","correct":"c1"},{"id":"r3","label":"Influenza","correct":"c1"},{"id":"r4","label":"Pertussis","correct":"c1"},{"id":"r5","label":"MRSA wound infection","correct":"c1"},{"id":"r6","label":"Scabies","correct":"c1"}]}','','0'),
('Set09-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Airway edema (hoarseness, angioedema), bronchospasm, hypoxemia, and hypotension indicate life-threatening anaphylaxis. The low-grade fever is related to the pyelonephritis.','Immune','Adult Health','{"segments":[{"id":"s1","text":"Hoarse voice","correct":true},{"id":"s2","text":"Audible expiratory wheezing","correct":true},{"id":"s3","text":"BP 78/42 mm Hg","correct":false},{"id":"s4","text":"HR 128/min","correct":false},{"id":"s5","text":"SpO2 89% on room air","correct":true},{"id":"s6","text":"Swelling of the lips and eyelids","correct":true},{"id":"s7","text":"Widespread hives","correct":true},{"id":"s8","text":"T 100.4°F (38°C)","correct":false}]}','RNMaster-Set09-Case','1'),
('Set09-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each finding, indicate the body system primarily affected. Airway/breathin','','','Airway/breathing: hoarseness, wheezing. Circulation: hypotension, tachycardia. Skin/mucosa: hives, itching. Mast cell mediators such as histamine cause laryngeal edema and bronchoconstriction, vasodilation and capillary leak (distributive shock), and skin manifestations. Anaphylaxis is diagnosed when multiple systems are involved.','Immune','Adult Health','{"columns":[{"id":"c1","label":"Circulation"},{"id":"c2","label":"Skin/mucosa"}],"rows":[{"id":"r1","label":"Hoarse voice","correct":"c2"},{"id":"r2","label":"Expiratory wheezing","correct":"c1"},{"id":"r3","label":"BP 78/42 mm Hg","correct":"c1"},{"id":"r4","label":"HR 128/min","correct":"c1"},{"id":"r5","label":"Widespread hives","correct":"c1"},{"id":"r6","label":"Itching","correct":"c1"}]}','RNMaster-Set09-Case','2'),
('Set09-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentences by choosing from the lists of options. The client is most likely experiencing ___1___. The most immediate threat to the client is ___2___.','','','obstruction from laryngeal edema Sudden onset of multi-system symptoms within minutes of a first-dose antibiotic indicates anaphylaxis. Septic shock does not cause hives, angioedema, and wheezing this abruptly. Hoarseness signals laryngeal edema, which can progress to complete airway obstruction.','Immune','Adult Health','{"blanks":[{"id":"b1","options":["anaphylaxis caused by ceftriaxone","septic shock from pyelonephritis","a panic attack","a vancomycin infusion reaction"],"correct":"anaphylaxis caused by ceftriaxone"},{"id":"b2","options":["airway obstruction from laryngeal edema","hypothermia","kidney stone formation","dehydration from fever"],"correct":"airway obstruction from laryngeal edema"}]}','RNMaster-Set09-Case','3'),
('Set09-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Stop the ceftriaxone infusion ☐|Epinephrine 0.5 mg IM (1 mg/mL) in the anterolateral thigh ☐|High-flow oxygen ☐|Rapid IV bolus of 0.9% sodium chloride ☐|Prepare for advanced airway management ☐|Continue the ceftriaxone at a slower rate ☐|Oral diphenhydramine as the only treatment','A,B,C,D,E','Anaphylaxis treatment is stopping the trigger, IM epinephrine (repeated every 5–15 minutes as needed), oxygen, fluid resuscitation for distributive shock, and airway readiness. Antihistamines, corticosteroids, and albuterol are adjuncts only. The antibiotic is never restarted.','Immune','Pharmacology','{}','RNMaster-Set09-Case','4'),
('Set09-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The nurse has stopped the ceftriaxone and called for help. Which medication should the nurse administer first?','Diphenhydramine IV|Epinephrine IM|Methylprednisolone IV|Nebulized albuterol','B','Epinephrine reverses bronchospasm, laryngeal edema, and vasodilation, and it is the only first-line drug for anaphylaxis. Delaying it increases mortality. The other drugs are adjuncts.','Immune','Pharmacology','{}','RNMaster-Set09-Case','5'),
('Set09-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','The client receives two doses of IM epinephrine, IV fluids, and oxygen. For each finding, indicate whether it shows improvement or requires immediate follow-up. Requires','','','Improved: BP 112/70, SpO2 96%, wheezing resolved, normal voice, hives fading. Follow-up: recurrent symptoms at 4 hours. Improved BP, oxygenation, airway, and skin show response to treatment. Symptom recurrence hours later is a biphasic reaction, which is why clients are observed after anaphylaxis and discharged with an epinephrine auto-injector and a documented allergy. Answers: Set 10: Integumentary System and Burns','Immune','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"BP 112/70 mm Hg","correct":"c1"},{"id":"r2","label":"SpO2 96% on 2 L/min nasal cannula","correct":"c1"},{"id":"r3","label":"Wheezing resolved","correct":"c1"},{"id":"r4","label":"Voice returned to normal","correct":"c1"},{"id":"r5","label":"Hives fading","correct":"c1"},{"id":"r6","label":"Four hours later: new throat tightness and hives recurring","correct":"c1"}]}','RNMaster-Set09-Case','6'),
('Set10-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Tachycardia, low BP, oliguria, and hemoconcentration indicate burn shock from capillary leak. Severe pain needs prompt treatment. The clear airway, intact pulses, and normal SpO2 are reassuring.','Integumentary','Adult Health','{"segments":[{"id":"s1","text":"HR 128/min","correct":false},{"id":"s2","text":"BP 96/60 mm Hg","correct":false},{"id":"s3","text":"Urine output 15 mL in the first hour","correct":true},{"id":"s4","text":"Hematocrit 54%","correct":true},{"id":"s5","text":"Pain 9/10","correct":true},{"id":"s6","text":"Voice clear, no soot in the mouth or nose","correct":false},{"id":"s7","text":"Pedal pulses palpable","correct":false},{"id":"s8","text":"SpO2 97% on room air","correct":false}]}','RNMaster-Set10-Case','1'),
('Set10-RN-21','Physiological Adaptation','Case study: Analyze cues','cloze_dropdown','Complete the sentences by choosing from the lists of options. Using the rule of nines, the client''s total body surface area burned is ___1___. Using the Parkland formula (4 mL × kg × %TBSA), the total volume of lactated Ringer''s for the first 24 hours is ___2___.','','','mL Anterior trunk (18%) plus the anterior surfaces of both legs (9% each) equals 36%. Parkland: 4 mL × 80 kg × 36 = 11,520 mL. Half (5,760 mL) is given in the first 8 hours from the time of injury, not arrival, and the rest over the next 16 hours. Rates are then adjusted to urine output.','Integumentary','Adult Health','{"blanks":[{"id":"b1","options":["27%","36%","45%","54%"],"correct":"36%"},{"id":"b2","options":["2,880 mL","5,760 mL","11,520 mL","14,400 mL"],"correct":"11,520 mL"}]}','RNMaster-Set10-Case','2'),
('Set10-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is at greatest risk for ___1___ because of ___2___.','','','capillary permeability with plasma shifting into the tissues Burns over about 20% TBSA cause massive capillary leak, which shifts fluid and protein into the interstitial space and depletes intravascular volume. There are no signs of inhalation injury, and the burns occurred outdoors.','Integumentary','Adult Health','{"blanks":[{"id":"b1","options":["hypovolemic (burn) shock","fluid volume excess","inhalation injury","hypoglycemia"],"correct":"hypovolemic (burn) shock"},{"id":"b2","options":["increased capillary permeability with plasma shifting into the tissues","excessive oral fluid intake","carbon monoxide exposure","adrenal insufficiency"],"correct":"increased capillary permeability with plasma shifting into the tissues"}]}','RNMaster-Set10-Case','3'),
('Set10-RN-23','Management of Care','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Infuse warmed lactated Ringer''s per the Parkland formula ☐|Titrate fluids to maintain urine output of about 0.5 mL/kg/hr (30–50 mL/hr) ☐|Administer IV opioids for pain ☐|Keep the client warm and cover burns with clean, dry sheets ☐|Give tetanus prophylaxis if immunization is not current ☐|Apply ice to the burned areas ☐|Administer morphine intramuscularly','A,B,C,D,E','Burn resuscitation uses isotonic crystalloid titrated to urine output. IV opioids treat pain, because IM absorption is unreliable with poor perfusion. Clients with large burns lose heat rapidly, so warmth is maintained. Tetanus prophylaxis is standard. Ice causes vasoconstriction, deepens the injury, and causes hypothermia.','Integumentary','Management of Care','{}','RNMaster-Set10-Case','4'),
('Set10-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Two large-bore IV catheters are in place. Which action should the nurse take first?','Apply topical antimicrobial cream to all burns|Begin lactated Ringer''s infusion at the calculated rate|Administer tetanus toxoid|Obtain photographs of the burns for the record','B','With a patent airway and adequate breathing, circulation is the priority. Fluid resuscitation prevents progression of burn shock and organ damage. Wound care and other measures follow.','Integumentary','Adult Health','{}','RNMaster-Set10-Case','5'),
('Set10-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Eight hours into resuscitation, the nurse reassesses the client. For each finding, indicate whether it shows effective treatment or requires follow-up. Requires','','','Effective: urine output 45 mL/hr, HR 104, BP 118/72, alert, Hct 44%. Follow-up: loss of left pedal pulse with increasing edema. Adequate urine output, improving hemodynamics, normal mentation, and falling hematocrit show effective resuscitation. Loss of a distal pulse with increasing edema under burned tissue suggests compromised circulation and may require escharotomy. Answers: Set 11: Fluids, Electrolytes, and Acid-Base Balance','Integumentary','Adult Health','{"columns":[{"id":"c1","label":"Effective"}],"rows":[{"id":"r1","label":"Urine output 45 mL/hr","correct":"c1"},{"id":"r2","label":"HR 104/min","correct":"c1"},{"id":"r3","label":"BP 118/72 mm Hg","correct":"c1"},{"id":"r4","label":"Alert and oriented","correct":"c1"},{"id":"r5","label":"Hematocrit 44%","correct":"c1"}]}','RNMaster-Set10-Case','6'),
('Set11-RN-2','Pharmacological and Parenteral Therapies','IV fluid tonicity','matrix_grid','For each IV solution, indicate whether it is isotonic, hypotonic, or hypertonic.','','','Isotonic: 0.9% NaCl, LR. Hypotonic: 0.45% NaCl, 0.225% NaCl. Hypertonic: 3% NaCl, D5 0.9% NaCl. Isotonic fluids expand intravascular volume. Hypotonic fluids shift water into cells. Hypertonic fluids pull water out of cells. D5W is isotonic in the bag but acts as hypotonic once the dextrose is metabolized.','Integrated','Pharmacology','{"columns":[{"id":"c1","label":"Isotonic"},{"id":"c2","label":"Hypotonic"},{"id":"c3","label":"Hypertonic"}],"rows":[{"id":"r1","label":"0.9% sodium chloride","correct":"c1"},{"id":"r2","label":"Lactated Ringer''s","correct":"c1"},{"id":"r3","label":"0.45% sodium chloride","correct":"c1"},{"id":"r4","label":"3% sodium chloride","correct":"c1"},{"id":"r5","label":"0.225% sodium chloride","correct":"c1"}]}','','0'),
('Set11-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Severe hypokalemia and hypomagnesemia with ventricular ectopy increase the risk of dysrhythmias, especially with digoxin. Orthostatic hypotension and oliguria indicate hypovolemia. Shallow respirations reflect respiratory muscle weakness and compensation for alkalosis. Sodium and temperature are normal.','Integrated','Adult Health','{"segments":[{"id":"s1","text":"Potassium 2.6 mEq/L","correct":false},{"id":"s2","text":"Frequent PVCs with U waves","correct":true},{"id":"s3","text":"Magnesium 1.4 mg/dL","correct":false},{"id":"s4","text":"Standing BP 86/50 mm Hg with near-fainting","correct":true},{"id":"s5","text":"Urine output 150 mL in 4 hours","correct":true},{"id":"s6","text":"RR 12/min and shallow","correct":true},{"id":"s7","text":"Sodium 136 mEq/L","correct":false},{"id":"s8","text":"Temperature 98.8°F","correct":false}]}','RNMaster-Set11-Case','1'),
('Set11-RN-21','Reduction of Risk Potential','Case study: Analyze cues','cloze_dropdown','Complete the sentences by choosing from the lists of options. The ABG indicates ___1___. The most likely causes are ___2___.','','','of gastric acid from vomiting and continued loop diuretic use The high pH and high HCO3 indicate metabolic alkalosis. The elevated PaCO2 shows respiratory compensation through hypoventilation, but the pH is not normal. Vomiting removes hydrochloric acid, and loop diuretics cause chloride, potassium, and volume loss that sustain the alkalosis.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["partially compensated metabolic alkalosis","uncompensated respiratory alkalosis","partially compensated metabolic acidosis","fully compensated respiratory acidosis"],"correct":"partially compensated metabolic alkalosis"},{"id":"b2","options":["loss of gastric acid from vomiting and continued loop diuretic use","diarrhea and bicarbonate loss","hyperventilation from anxiety","kidney failure with acid retention"],"correct":"loss of gastric acid from vomiting and continued loop diuretic use"}]}','RNMaster-Set11-Case','2'),
('Set11-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client''s most immediate threat is ___1___ related to ___2___.','','','and hypomagnesemia in a client taking digoxin Low potassium and magnesium increase myocardial irritability and greatly increase the risk of digoxin toxicity, which can cause ventricular dysrhythmias. Hypovolemia is serious, but the client is stable while lying down.','Integrated','Adult Health','{"blanks":[{"id":"b1","options":["a life-threatening cardiac dysrhythmia","fluid volume excess","hypoglycemia","a seizure from hyponatremia"],"correct":"a life-threatening cardiac dysrhythmia"},{"id":"b2","options":["hypokalemia and hypomagnesemia in a client taking digoxin","hypernatremia","elevated creatinine","a low-grade fever"],"correct":"hypokalemia and hypomagnesemia in a client taking digoxin"}]}','RNMaster-Set11-Case','3'),
('Set11-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','IV potassium chloride by infusion pump at a safe rate ☐|IV magnesium sulfate replacement ☐|Continuous cardiac monitoring ☐|IV 0.9% sodium chloride infusion ☐|Hold furosemide and digoxin pending provider review and a digoxin level ☐|Potassium chloride 40 mEq IV push ☐|Encourage the client to get up and walk independently to the bathroom','A,B,C,D,E','Treatment includes safe IV potassium and magnesium replacement, cardiac monitoring, and isotonic saline, which also corrects chloride-responsive alkalosis. The diuretic and digoxin are held and a digoxin level is checked. IV push potassium is lethal, and the client is at high fall risk from orthostatic hypotension.','Integrated','Pharmacology','{}','RNMaster-Set11-Case','4'),
('Set11-RN-24','Pharmacological and Parenteral Therapies','Case study: Take action','single_best_answer','The nurse is preparing to start the IV potassium chloride infusion. Which action is most important before beginning?','Confirm the client has adequate urine output|Give the potassium with a meal|Check the client''s blood glucose|Place the client in Trendelenburg position','A','Potassium is excreted by the kidneys. Giving potassium to a client with inadequate urine output can cause hyperkalemia. The client''s low output should be addressed with the provider, often with fluids started first or concurrently, and output monitored closely.','Integrated','Pharmacology','{}','RNMaster-Set11-Case','5'),
('Set11-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Twenty-four hours later, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires follow-up. Requires','','','Improved: K 3.8, no PVCs, normal standing BP, normal pH/HCO3, Mg 1.9. Follow-up: burning, redness, and cord along the IV vein. Normalized electrolytes, acid-base balance, rhythm, and orthostatic BP show effective treatment. Burning, redness, and a palpable cord indicate phlebitis, which is common with potassium infusions. The IV is removed and restarted at another site. Answers: Set 12: Maternity and Newborn','Integrated','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"Potassium 3.8 mEq/L","correct":"c1"},{"id":"r2","label":"No PVCs on the monitor","correct":"c1"},{"id":"r3","label":"Standing BP 118/70 mm Hg without dizziness","correct":"c1"},{"id":"r4","label":"pH 7.43, HCO3 27 mEq/L","correct":"c1"},{"id":"r5","label":"Magnesium 1.9 mg/dL","correct":"c1"},{"id":"r6","label":"Burning pain, redness, and a firm cord along the IV vein","correct":"c1"}]}','RNMaster-Set11-Case','6'),
('Set12-RN-3','Reduction of Risk Potential','Fetal heart rate patterns','matrix_grid','For each fetal heart rate finding, indicate the most likely cause. Head                      Cord          Uteroplacental Finding','','','A memory aid is VEAL CHOP: Variable = Cord compression, Early = Head compression, Accelerations = OK, Late = Placental insufficiency. Early decelerations are benign; variable and late decelerations require intervention.','Maternal & Newborn','Adult Health','{"columns":[{"id":"c1","label":"compression"},{"id":"c2","label":"insufficiency"}],"rows":[{"id":"r1","label":"Early deceleration","correct":"c1"},{"id":"r2","label":"Variable deceleration","correct":"c1"},{"id":"r3","label":"Late deceleration","correct":"c1"}]}','','0'),
('Set12-RN-20','Physiological Adaptation','Case study: Recognize cues','highlight','Highlight (circle) the findings that require immediate follow-up.','','','Heavy bleeding with a boggy fundus indicates uterine atony. A deviated, elevated fundus suggests a full bladder preventing contraction. Tachycardia, falling BP, and blood loss over 500 mL after vaginal birth indicate hemorrhage. Blood type and SpO2 are not immediate concerns.','Maternal & Newborn','Adult Health','{"segments":[{"id":"s1","text":"Pad saturated in 15 minutes with large clots","correct":true},{"id":"s2","text":"Fundus boggy and 2 cm above the umbilicus","correct":true},{"id":"s3","text":"Fundus deviated to the right","correct":true},{"id":"s4","text":"HR 118/min","correct":false},{"id":"s5","text":"BP 92/58 mm Hg","correct":false},{"id":"s6","text":"Quantitative blood loss 950 mL","correct":false},{"id":"s7","text":"Blood type O positive","correct":false},{"id":"s8","text":"SpO2 97% on room air","correct":false}]}','RNMaster-Set12-Case','1'),
('Set12-RN-21','Physiological Adaptation','Case study: Analyze cues','matrix_grid','For each factor, indicate whether it contributes to this client''s uterine atony. Not a Contributing','','','Contributing: macrosomia, prolonged oxytocin labor, distended bladder. Not contributing: age 32, breastfeeding, blood type. Uterine overdistention (macrosomia), a fatigued uterus after prolonged oxytocin exposure, and a full bladder impair contraction. Breastfeeding releases endogenous oxytocin and helps the uterus contract.','Maternal & Newborn','Adult Health','{"columns":[{"id":"c1","label":"contributing"}],"rows":[{"id":"r1","label":"Newborn weighing 4,200 g","correct":"c1"},{"id":"r2","label":"Prolonged labor with oxytocin augmentation","correct":"c1"},{"id":"r3","label":"Distended bladder","correct":"c1"},{"id":"r4","label":"Maternal age of 32 years","correct":"c1"},{"id":"r5","label":"Early initiation of breastfeeding","correct":"c1"},{"id":"r6","label":"Blood type O positive","correct":"c1"}]}','RNMaster-Set12-Case','2'),
('Set12-RN-22','Physiological Adaptation','Case study: Prioritize hypotheses','cloze_dropdown','Complete the sentence by choosing from the lists of options. The client is experiencing ___1___ caused by ___2___.','','','atony Blood loss over 500 mL after vaginal birth (or 1,000 mL cumulative with signs of hypovolemia) with tachycardia and falling BP indicates hemorrhage. A boggy fundus identifies atony, the most common cause. The placenta delivered intact, which makes retained tissue less likely.','Maternal & Newborn','Adult Health','{"blanks":[{"id":"b1","options":["postpartum hemorrhage with early hypovolemic shock","normal postpartum lochia","amniotic fluid embolism","postpartum preeclampsia"],"correct":"postpartum hemorrhage with early hypovolemic shock"},{"id":"b2","options":["uterine atony","a retained placenta","uterine inversion","a coagulation disorder"],"correct":"uterine atony"}]}','RNMaster-Set12-Case','3'),
('Set12-RN-23','Pharmacological and Parenteral Therapies','Case study: Generate solutions','multiple_response','Which interventions does the nurse anticipate? Select all that apply. ☐','Vigorous fundal massage ☐|Catheterize to empty the bladder ☐|Resume or increase the IV oxytocin infusion ☐|Administer methylergonovine IM as prescribed ☐|Administer tranexamic acid IV as prescribed ☐|Encourage the client to walk to the bathroom to void ☐|Withhold IV fluids to prevent fluid overload','A,B,C,D,E','Fundal massage, emptying the bladder, and uterotonics (oxytocin, then methylergonovine or carboprost if not contraindicated) treat atony. Tranexamic acid reduces bleeding. IV fluids and blood products restore volume. Ambulating is unsafe with hypovolemia. Methylergonovine is safe here because the client is not hypertensive.','Maternal & Newborn','Pharmacology','{}','RNMaster-Set12-Case','4'),
('Set12-RN-24','Physiological Adaptation','Case study: Take action','single_best_answer','Which action should the nurse take first?','Massage the fundus|Insert a urinary catheter|Administer methylergonovine IM|Obtain a hemoglobin level','A','Fundal massage is the immediate first action for a boggy uterus with heavy bleeding. The nurse calls for help while massaging, then empties the bladder and gives uterotonics.','Maternal & Newborn','Adult Health','{}','RNMaster-Set12-Case','5'),
('Set12-RN-25','Physiological Adaptation','Case study: Evaluate outcomes','matrix_grid','Two hours after interventions, the nurse reassesses the client. For each finding, indicate whether it shows improvement or requires follow-up. Requires','','','Improved: firm midline fundus, moderate lochia, HR 88, bladder emptied, warm dry skin. Follow-up: headache with BP 152/100. A firm midline fundus, controlled bleeding, and normalized heart rate and perfusion show effective treatment. Methylergonovine causes vasoconstriction and can cause hypertension and headache, which must be reported and further doses held. Answers: Set 13: Pediatrics','Maternal & Newborn','Adult Health','{"columns":[{"id":"c1","label":"Improved"}],"rows":[{"id":"r1","label":"Fundus firm, midline, at the umbilicus","correct":"c1"},{"id":"r2","label":"Moderate lochia rubra, less than 1 pad per hour","correct":"c1"},{"id":"r3","label":"HR 88/min","correct":"c1"},{"id":"r4","label":"Urine output 400 mL after catheterization","correct":"c1"},{"id":"r5","label":"Skin warm and dry","correct":"c1"}]}','RNMaster-Set12-Case','6')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline,response_config,caseid,case_sequence) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method,case_set_id,case_study_id,case_sequence) values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Evaluate each response against the source key and clinical task.','Interpret the case cues and respond in the native NCLEX item format.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,r.response_config::jsonb,case when r.item_type='multiple_response' then 'plus_minus' when r.item_type='single_best_answer' then 'zero_one' else r.item_type end,nullif(r.caseid,''),nullif(r.caseid,''),case when r.case_sequence::int>0 then r.case_sequence::int else null end) on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,response_config=excluded.response_config,source_id=excluded.source_id,case_set_id=excluded.case_set_id,case_study_id=excluded.case_study_id,case_sequence=excluded.case_sequence,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid;
 if r.item_type in ('single_best_answer','multiple_response') then keyarr:=string_to_array(r.keys,','); n:=0; for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop; select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid; if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source answer mapped to native response model; clinical review pending.' where id=qvid;
end loop; end $$; commit;